mapper.select:
select t.ride_type,t.ride_type rideType,t.status_cd,t.status_cd statusCd,t.ac_machine_code,t.ac_machine_code
acMachineCode,t.machine_name,t.machine_name machineName,t.ac_machine_name,t.ac_machine_name
acMachineName,t.room_name,t.room_name roomName,t.layer,t.ac_machine_id,t.ac_machine_id
acMachineId,t.machine_id,t.machine_id machineId,t.name,t.log_id,t.log_id logId,t.tel,t.face_path,t.face_path
facePath,t.person_type,t.person_type personType,t.community_id,t.community_id communityId
from lift_ride_log t
where 1 =1

    and t.ride_type= #{rideType}


    and t.status_cd= #{statusCd}


    and t.ac_machine_code= #{acMachineCode}


    and t.machine_name= #{machineName}


    and t.ac_machine_name= #{acMachineName}


    and t.room_name= #{roomName}


    and t.layer= #{layer}


    and t.ac_machine_id= #{acMachineId}


    and t.machine_id= #{machineId}


    and t.name= #{name}


    and t.log_id= #{logId}


    and t.tel= #{tel}


    and t.face_path= #{facePath}


    and t.person_type= #{personType}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

